const lessons=[
 {id:'packet',track:'network',title:'ข้อมูลเดินทางอย่างไร',subtitle:'ตาม Packet จากเครื่องของเรา ผ่าน Switch และ Router ไปถึง Server',time:15,visual:'network',tag:'PACKET JOURNEY',scenario:'คุณเปิดระบบติดตามอุปกรณ์ของบริษัท ข้อมูลจากเครื่องคุณต้องผ่านอะไรบ้างก่อนถึง Server?',explain:'Client เป็นฝ่ายเริ่มขอข้อมูล ส่วน Server ให้บริการ Switch ส่งข้อมูลภายในเครือข่ายเดียวกัน เมื่อปลายทางอยู่คนละเครือข่าย Router จะช่วยส่งต่อไปยังเส้นทางที่เหมาะสม',steps:['เลือกปลายทางของข้อมูล','กดส่ง Packet แล้วดูอุปกรณ์ที่ข้อมูลผ่าน','ตอบภารกิจเพื่อบันทึกบทเรียน'],question:'ถ้า Server อยู่คนละเครือข่ายกับ Client อุปกรณ์ใดช่วยส่งข้อมูลออกจากเครือข่ายของ Client?',choices:['Switch อย่างเดียว','Router / Default gateway','เครื่อง Client เครื่องอื่น'],answer:1,reason:'Router เชื่อมเครือข่ายต่างกัน ส่วน Switch ในแบบจำลองนี้ส่งข้อมูลภายใน LAN',hint:'มองหาอุปกรณ์ที่เชื่อมระหว่างเครือข่ายสองฝั่ง',work:'เวลาอ่านแผนผังระบบ ให้เริ่มจาก Client และปลายทาง แล้วไล่ดูอุปกรณ์ระหว่างทาง',source:'https://developer.mozilla.org/en-US/docs/Learn_web_development/Howto/Web_mechanics/How_does_the_Internet_work'},
 {id:'gateway',track:'network',title:'ทำไมอุปกรณ์เชื่อมต่อไม่ได้',subtitle:'แก้ Gateway ผิด แล้วดูว่า Packet หยุดอยู่ตรงไหน',time:20,visual:'rack',tag:'TROUBLESHOOTING',scenario:'Client ได้ IP 192.168.10.25/24 แต่เชื่อมต่อ Server 10.0.0.10 ไม่ได้ Router ของเครือข่ายนี้ใช้ IP 192.168.10.1',explain:'Default gateway คือที่อยู่ของ Router ที่เครื่องใช้ส่งข้อมูลไปยังเครือข่ายอื่น ในตัวอย่างนี้ต้องเป็น Router ที่เข้าถึงได้บน LAN เดียวกัน การมี IP แล้วจึงยังไม่รับประกันว่าเชื่อมต่อปลายทางได้',steps:['ลองส่งข้อมูลด้วย Gateway ที่ตั้งไว้','เปลี่ยน Gateway ให้ตรงกับ Router','ส่งข้อมูลอีกครั้ง แล้วอธิบายสาเหตุ'],question:'ค่า Gateway ใดทำให้ Client 192.168.10.25/24 ส่งข้อมูลออกไปได้ในแบบจำลองนี้?',choices:['192.168.10.1','192.168.10.254','10.0.0.10'],answer:0,reason:'192.168.10.1 คือ Router ที่กำหนดไว้ใน LAN นี้ เลข .254 ไม่ได้เป็น Gateway โดยอัตโนมัติ และ IP ของ Server ก็ไม่ใช่ Gateway ของ Client',hint:'ดู IP ของ Router ในสถานการณ์ อย่าเลือกจากเลขท้ายที่คุ้นเคย',work:'เมื่อเข้า Server ไม่ได้ ให้ตรวจ IP, subnet mask และ Gateway ก่อน แล้วค่อยตรวจเส้นทางและบริการ',source:'https://www.rfc-editor.org/rfc/rfc1122'},
 {id:'dns',track:'network',title:'ชื่อเว็บไซต์กลายเป็น IP ได้อย่างไร',subtitle:'ทดลอง DNS แล้วแยกปัญหาเรื่องชื่อออกจากการเชื่อมต่อ',time:15,visual:'network',tag:'DNS & HTTP',scenario:'คุณเปิด ops.example.test แต่ระบบแจ้งว่าหาชื่อไม่พบ ขณะที่ Server 10.0.0.10 ยังให้บริการได้',explain:'DNS ช่วยหาที่อยู่ IP จากชื่อ เมื่อได้ IP แล้ว Client จึงเชื่อมต่อบริการ เช่น HTTP/HTTPS ต่อไป DNS สำเร็จไม่ได้รับประกันว่าบริการปลายทางจะตอบ',steps:['ทดลองชื่อที่มีและไม่มีใน DNS จำลอง','ดู IP ที่ได้ก่อนส่ง HTTP request','ตอบคำถามเพื่อแยกสาเหตุ'],question:'เปิดด้วย IP ได้ แต่ชื่อ ops.example.test ใช้ไม่ได้ ควรตรวจอะไรเป็นลำดับแรก?',choices:['DNS และรายการชื่อ','เปลี่ยนสายทุกเส้นทันที','จำนวนตัวแปรใน Python'],answer:0,reason:'อาการนี้ชี้ให้ตรวจการค้นชื่อก่อน เพราะการเข้าถึงด้วย IP ยังทำงานได้ แต่อาจต้องตรวจการตั้งค่า Host/TLS เพิ่มในระบบจริง',hint:'สิ่งใดเปลี่ยนชื่อที่อ่านง่ายให้เป็นที่อยู่ของเครื่อง?',work:'แยกการค้นชื่อกับการเชื่อมต่อ เพื่อให้รายงานปัญหามีหลักฐานที่ชัดเจน',source:'https://developer.mozilla.org/en-US/docs/Learn_web_development/Howto/Web_mechanics/What_is_a_domain_name'},
 {id:'protocols',track:'network',title:'TCP, UDP และ Port',subtitle:'เลือกวิธีส่งข้อมูลและบริการ แล้วอ่านผลที่ต่างกัน',time:18,visual:'rack',tag:'TRANSPORT',scenario:'ระบบมีบริการเว็บผ่าน HTTPS บน TCP port 443 และตัวรับข้อมูลจำลองบน UDP port 5000 คุณต้องส่งข้อมูลให้ตรงกับบริการ',explain:'TCP ส่งข้อมูลเป็น stream พร้อมกลไกจัดลำดับและส่งซ้ำ UDP ส่งเป็น datagram โดยไม่มีการรับประกันเหล่านั้นในตัวโปรโตคอล Port ช่วยแยกบริการบนเครื่องเดียวกัน ทั้งชนิดโปรโตคอลและ Port ต้องตรงกับบริการ',steps:['เลือก TCP หรือ UDP และ Port','ทดลองส่งไปยังบริการจำลอง','สังเกตผลเมื่อเลือกบริการไม่ตรง'],question:'บริการ HTTPS ของสถานการณ์นี้รับการเชื่อมต่อที่ใด?',choices:['TCP port 443','UDP port 443','TCP port 5000'],answer:0,reason:'บริการในแบบจำลองนี้กำหนดเป็น TCP/443 โปรโตคอลและ Port เป็นส่วนของปลายทางบริการ ไม่ใช่เลข IP',hint:'อ่านค่าบริการที่กำหนดไว้ในสถานการณ์',work:'เวลาอ่าน Log ให้แยก source/destination IP, Port และ Protocol จะช่วยระบุการเชื่อมต่อได้ถูกต้อง',source:'https://developer.mozilla.org/en-US/docs/Glossary/TCP'},
 {id:'address',track:'network',title:'IP, MAC และเครือข่ายเดียวกัน',subtitle:'ดูว่าเมื่อใดส่งตรงใน LAN และเมื่อใดต้องผ่าน Gateway',time:18,visual:'network',tag:'ADDRESSING',scenario:'Client ใช้ 192.168.10.25/24 เครื่อง SW-01 ใช้ 192.168.10.2 และ Server ใช้ 10.0.0.10 คุณจะส่งข้อมูลถึงแต่ละเครื่องอย่างไร?',explain:'IP ใช้ระบุที่อยู่ในเครือข่าย IP ส่วน MAC ใช้ระบุปลายทางของ frame บน link เช่น Ethernet ในสถานการณ์ /24 นี้ 192.168.10.25 กับ 192.168.10.2 อยู่ subnet เดียวกัน ส่วน 10.0.0.10 อยู่คนละ subnet',steps:['เลือกเครื่องใน LAN หรือ Server อีกเครือข่าย','ดูว่าข้อมูลผ่าน Router หรือไม่','ตอบคำถามจาก IP และ prefix'],question:'ปลายทางใดอยู่ subnet เดียวกับ 192.168.10.25/24?',choices:['192.168.10.2','192.168.11.2','10.0.0.10'],answer:0,reason:'สำหรับ /24 สามส่วนแรกของ IP เป็นส่วน network จึงอยู่ใน 192.168.10.0/24 เหมือนกัน',hint:'บทนี้กำหนด /24 ไว้แล้ว ลองเทียบสามส่วนแรกของ IP',work:'อ่านทั้ง IP และ prefix เสมอ การดู IP เพียงอย่างเดียวบอกขอบเขต subnet ไม่ครบ',source:'https://www.rfc-editor.org/rfc/rfc791'},
 {id:'subnet',track:'network',title:'แบ่งเครือข่ายด้วย Subnet',subtitle:'ปรับ /24, /25 และ /26 แล้วเห็นขอบเขตและจำนวนที่อยู่',time:25,visual:'subnet',tag:'SUBNET LAB',scenario:'คุณมีเครือข่าย 192.168.10.0/24 และต้องการแบ่งเป็น 4 subnet ขนาดเท่ากันสำหรับ 4 แผนก',explain:'Prefix บอกจำนวนบิตของส่วน network เมื่อเพิ่มจาก /24 เป็น /26 จะยืม 2 บิต ทำให้ได้ 4 subnet แต่ละ subnet มี 64 ที่อยู่ สำหรับ LAN IPv4 แบบปกติจะเหลือ 62 ที่อยู่ใช้งานหลังหัก network และ broadcast',steps:['เปลี่ยน prefix และอ่านช่วง IP','เลือก prefix ที่แบ่งได้ 4 subnet','ตอบจำนวนที่อยู่ที่ใช้งานได้'],question:'แบ่ง 192.168.10.0/24 เป็น 4 subnet เท่ากัน แต่ละ subnet ใช้ prefix ใด?',choices:['/24','/25','/26'],answer:2,reason:'/26 ยืม 2 บิตจาก /24 จึงได้ 2² = 4 subnet ขนาดละ 64 ที่อยู่ (62 host สำหรับ LAN ปกติ)',hint:'ต้องการ 4 subnet หมายถึง 2 ยกกำลังอะไร?',work:'การแบ่ง subnet ช่วยวางแผนช่วง IP ให้แต่ละกลุ่ม บทนี้ใช้ LAN ทั่วไปและยังไม่ครอบคลุมกรณี /31 หรือ /32',source:'https://www.rfc-editor.org/rfc/rfc4632'},
 {id:'variables',track:'python',title:'ตัวแปร: ข้อมูลของอุปกรณ์หนึ่งตัว',subtitle:'เก็บชื่อ IP และจำนวน Alarm แล้วแสดงผลด้วย Python',time:15,visual:'python',tag:'PYTHON / 01',scenario:'เริ่มจากอุปกรณ์ AP-02 หนึ่งตัว เก็บจำนวน Alarm และแสดงออกมาให้คนอ่านได้',explain:'ตัวแปรผูกชื่อกับค่า String เก็บข้อความ เช่นชื่ออุปกรณ์ ส่วน Integer เก็บจำนวนเต็ม เช่นจำนวน Alarm ใช้ print() เพื่อแสดงผล',steps:['อ่านค่าตัวแปรในโค้ด','เพิ่ม print(alarms) เพื่อแสดงจำนวน','รันและตรวจผลลัพธ์'],starter:'device_name = "AP-02"\nalarms = 3\n\nprint(device_name)\n# เพิ่มบรรทัดแสดงจำนวน alarms ด้านล่าง\n',expected:'AP-02\n3',hint:'เพิ่ม print(alarms) ต่อจากบรรทัด print(device_name)',solution:'device_name = "AP-02"\nalarms = 3\nprint(device_name)\nprint(alarms)',work:'ข้อมูลพื้นฐานของอุปกรณ์มักประกอบด้วยข้อความและตัวเลข การเลือกชนิดข้อมูลช่วยให้คำนวณต่อได้',source:'https://docs.python.org/3/tutorial/introduction.html'},
 {id:'conditions',track:'python',title:'เงื่อนไข: ตัดสินใจจากสถานะ',subtitle:'ใช้ if เพื่อแสดงคำเตือนเมื่ออุปกรณ์ Offline',time:18,visual:'python',tag:'PYTHON / 02',scenario:'อุปกรณ์มีสถานะ offline ต้องแสดงข้อความ CHECK โดยไม่เตือนอุปกรณ์ที่ยัง online',explain:'if จะทำงานเมื่อเงื่อนไขเป็นจริง เครื่องหมาย == ใช้เปรียบเทียบค่า ส่วน = ใช้กำหนดค่า Python ใช้การเยื้องบรรทัดเพื่อบอกว่าโค้ดใดอยู่ในเงื่อนไข',steps:['อ่านค่า status','แก้เงื่อนไขให้ตรวจ offline','รันเพื่อดูข้อความ CHECK'],starter:'status = "offline"\n\nif status == "online":\n    print("CHECK")\n',expected:'CHECK',hint:'เงื่อนไขควรเป็น status == "offline"',solution:'status = "offline"\nif status == "offline":\n    print("CHECK")',work:'เงื่อนไขใช้กำหนดว่าจะจัดการข้อมูลใด เช่น Offline, Alarm สูง หรือข้อมูลไม่ครบ',source:'https://docs.python.org/3/tutorial/controlflow.html'},
 {id:'loops',track:'python',title:'Loop: ตรวจหลายอุปกรณ์',subtitle:'วนอ่านรายการและแสดงชื่ออุปกรณ์ทีละตัว',time:18,visual:'python',tag:'PYTHON / 03',scenario:'มีชื่ออุปกรณ์ 3 ตัว การเขียน print แยกทุกตัวจะดูแลยากเมื่อรายการยาวขึ้น',explain:'List เก็บหลายค่าไว้ตามลำดับ for จะอ่านแต่ละค่าในรายการ แล้วทำคำสั่งในบล็อกซ้ำ โดยตัวแปร name เปลี่ยนไปตามรายการ',steps:['ดูรายการ names','แทน pass ด้วยคำสั่งแสดง name','รันและเทียบลำดับผลลัพธ์'],starter:'names = ["SW-01", "RT-01", "AP-02"]\n\nfor name in names:\n    pass  # แสดง name ในบรรทัดนี้\n',expected:'SW-01\nRT-01\nAP-02',hint:'ใช้ print(name) ภายใน for และคงการเยื้อง 4 ช่องไว้',solution:'names = ["SW-01", "RT-01", "AP-02"]\nfor name in names:\n    print(name)',work:'Loop เป็นฐานสำหรับประมวลผลรายการอุปกรณ์หรือ Log จำนวนมาก',source:'https://docs.python.org/3/tutorial/controlflow.html'},
 {id:'functions',track:'python',title:'Function: ใช้กติกาเดิมซ้ำ',subtitle:'สร้างฟังก์ชันตรวจสถานะแล้วคืนค่า True หรือ False',time:20,visual:'python',tag:'PYTHON / 04',scenario:'ทั้งรายงานประจำวันและหน้าสรุป Incident ต้องใช้กติกาตรวจ Offline เหมือนกัน',explain:'Function รวมกติกาที่เรียกซ้ำได้ Parameter รับข้อมูลเข้ามา ส่วน return ส่งผลลัพธ์ออกไป ฟังก์ชัน is_offline ควรคืนค่า True เฉพาะเมื่อสถานะเป็น offline',steps:['อ่านฟังก์ชันและจุดที่เรียกใช้','แก้ return ให้เปรียบเทียบสถานะ','ตรวจทั้ง offline และ online'],starter:'def is_offline(status):\n    return False  # แก้ให้คืนผลการเปรียบเทียบ\n\nprint(is_offline("offline"))\nprint(is_offline("online"))\n',expected:'True\nFalse',hint:'return status == "offline" จะคืนผล True หรือ False ตามค่า status',solution:'def is_offline(status):\n    return status == "offline"\nprint(is_offline("offline"))\nprint(is_offline("online"))',work:'แยกกติกาที่ใช้ร่วมกันเป็นฟังก์ชัน เพื่อลดการแก้หลายจุดและตรวจผลได้ง่าย',source:'https://docs.python.org/3/tutorial/controlflow.html#defining-functions'},
 {id:'collections',track:'python',title:'Dictionary: อ่านข้อมูลให้ถูกช่อง',subtitle:'เก็บชื่อ IP และ Alarm ของอุปกรณ์ไว้ด้วยกัน',time:18,visual:'python',tag:'PYTHON / 05',scenario:'ข้อมูลอุปกรณ์หนึ่งตัวมีหลายช่อง ต้องอ่านจำนวน Alarm จากช่องที่ถูกต้อง และรองรับช่องที่ยังไม่มี',explain:'Dictionary เก็บค่าด้วย key เช่น name หรือ alarms ใช้ device["alarms"] เมื่อมั่นใจว่ามี key ส่วน get("alarms", 0) กำหนดค่าเริ่มต้นได้เมื่อข้อมูลขาด',steps:['ดู key และ value ของอุปกรณ์','อ่าน alarms และ missing key ผ่าน get','ตรวจว่าข้อมูลขาดแล้วไม่เกิด KeyError'],starter:'device = {"name": "AP-02", "ip": "192.168.10.20", "alarms": 3}\n\nprint(device["name"])\n# แสดง alarms และค่าเริ่มต้นของช่อง errors ที่ไม่มี\n',expected:'AP-02\n3\n0',hint:'เพิ่ม print(device["alarms"]) และ print(device.get("errors", 0))',solution:'device = {"name": "AP-02", "ip": "192.168.10.20", "alarms": 3}\nprint(device["name"])\nprint(device["alarms"])\nprint(device.get("errors", 0))',work:'รูปแบบข้อมูล API และ JSON มักคล้าย Dictionary การตรวจช่องที่ขาดช่วยให้โปรแกรมทนต่อข้อมูลที่ไม่ครบ',source:'https://docs.python.org/3/tutorial/datastructures.html#dictionaries'},
 {id:'offline',track:'python',title:'ใช้ Python หาอุปกรณ์ที่ Offline',subtitle:'รวม List, Dictionary, Loop และ if ให้เป็นเครื่องมือแรกของคุณ',time:25,visual:'python',tag:'PYTHON / FIELD LAB',scenario:'ทีมต้องการรายชื่ออุปกรณ์ Offline และจำนวน Alarm รวมจากรายการอุปกรณ์ 4 ตัว',explain:'List เก็บรายการอุปกรณ์ แต่ละตัวเป็น Dictionary ใช้ for อ่านแต่ละตัว แล้ว if เลือกเฉพาะสถานะ offline ตัวแปร total ใช้รวม Alarm ของอุปกรณ์ที่เลือก',steps:['ดูข้อมูลอุปกรณ์และเงื่อนไขในโค้ด','เปลี่ยน online ให้กรอง offline','เพิ่มจำนวน Alarm แล้วรันเพื่อตรวจผล'],starter:'devices = [\n    {"name": "SW-01", "status": "online", "alarms": 0},\n    {"name": "RT-01", "status": "online", "alarms": 0},\n    {"name": "AP-02", "status": "offline", "alarms": 3},\n    {"name": "SW-03", "status": "offline", "alarms": 2},\n]\n\ntotal = 0\nfor device in devices:\n    if device["status"] == "online":\n        print(device["name"])\n        # เพิ่ม alarms ของอุปกรณ์นี้ลงใน total\n\nprint("alarms:", total)\n',expected:'AP-02\nSW-03\nalarms: 5',hint:'เปลี่ยนเงื่อนไขเป็น "offline" แล้วเพิ่ม total += device["alarms"] ภายใน if',solution:'devices = [{"name":"SW-01","status":"online","alarms":0},{"name":"RT-01","status":"online","alarms":0},{"name":"AP-02","status":"offline","alarms":3},{"name":"SW-03","status":"offline","alarms":2}]\ntotal = 0\nfor device in devices:\n    if device["status"] == "offline":\n        print(device["name"])\n        total += device["alarms"]\nprint("alarms:", total)',work:'นี่คือจุดเริ่มต้นของรายงานสถานะอัตโนมัติ บทถัดไปจะต่อยอดไปอ่านไฟล์และ API แทนข้อมูลในโค้ด',source:'https://docs.python.org/3/tutorial/'}
];
const phases=[['Network พื้นฐาน','เข้าใจอุปกรณ์ การเดินทางของข้อมูล และการตรวจปัญหาเบื้องต้น','network'],['Python พื้นฐาน','เปลี่ยนข้อมูลอุปกรณ์เป็นโปรแกรมเล็ก ๆ ที่ช่วยงานได้','python'],['Python สำหรับงานข้อมูล','อ่าน CSV / JSON วิเคราะห์ Log เรียก API และออกรายงาน','data'],['JavaScript','ต่อยอดจาก Python สู่หน้าเว็บที่แสดงข้อมูลอุปกรณ์','javascript'],['TypeScript & Node.js','กำหนดรูปแบบข้อมูลและสร้างบริการ API','backend'],['AI พื้นฐาน','เขียน Prompt ตรวจหลักฐาน และเข้าใจข้อจำกัดของคำตอบ','ai'],['AI สำหรับสร้างเครื่องมือ','เชื่อม Python กับโมเดล ค้นคู่มือและประเมินคุณภาพคำตอบ','applied-ai']];
const terms=[['Packet','หน่วยข้อมูลที่ส่งผ่านเครือข่าย มีข้อมูลปลายทางและเนื้อหาที่ต้องการส่ง'],['Client / Server','Client เริ่มร้องขอข้อมูล ส่วน Server ให้บริการและตอบกลับ'],['Switch','อุปกรณ์ที่ส่ง frame ระหว่างอุปกรณ์บน LAN โดยอาศัยที่อยู่ MAC'],['Router / Gateway','Router ส่งข้อมูลระหว่างเครือข่าย ส่วน Default gateway คือที่อยู่ Router ที่เครื่องใช้ไปยังเครือข่ายอื่น'],['IP / MAC','IP เป็นที่อยู่ในเครือข่าย IP ส่วน MAC ใช้ระบุปลายทาง frame บน link เช่น Ethernet'],['Subnet / CIDR','Subnet คือเครือข่ายย่อย ส่วน /24 หรือ /26 บอกจำนวนบิตของส่วน network'],['DNS','ระบบค้นที่อยู่ IP จากชื่อ เช่น ops.example.test'],['DHCP','บริการแจกค่าการตั้งค่าเครือข่าย เช่น IP, subnet mask, Gateway และ DNS'],['Port','หมายเลขที่ใช้แยกบริการหรือการสื่อสารบนเครื่อง ร่วมกับ IP และ Protocol'],['TCP / UDP','TCP มีกลไกจัดลำดับและส่งซ้ำ UDP ส่งเป็น datagram โดยไม่มีการรับประกันดังกล่าวในตัวโปรโตคอล'],['List / Dictionary','List เก็บหลายค่าตามลำดับ Dictionary เก็บค่าผูกกับชื่อ key'],['API','ข้อตกลงที่โปรแกรมใช้ร้องขอข้อมูลหรือบริการจากโปรแกรมอื่น']];
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let progress={};let storageAvailable=true;try{progress=JSON.parse(localStorage.getItem('techatlas-progress-v1')||'{}');if(!progress||typeof progress!=='object'||Array.isArray(progress))progress={};}catch{storageAvailable=false;progress={};}
let scenes=[];let disposed=false;let currentLesson=null;let worker=null;let workerReady=false;let runTimer=null;let initTimer=null;let drafts={};try{drafts=JSON.parse(localStorage.getItem('techatlas-drafts-v1')||'{}');if(!drafts||typeof drafts!=='object')drafts={};}catch{}
const countDone=()=>lessons.filter(l=>progress[l.id]).length;
function updateBadge(){document.querySelector('#nav-progress').textContent=countDone();}
function complete(id){if(!lessons.some(l=>l.id===id))return;progress[id]={completedAt:new Date().toISOString()};try{localStorage.setItem('techatlas-progress-v1',JSON.stringify(progress));}catch{storageAvailable=false;}updateBadge();}
function addScene(el,options){const generation=disposed;return import('./scene.js').then(({mountScene})=>{if(!el.isConnected||generation!==disposed)return null;try{const scene=mountScene(el,options);scene.container=el;if(options.variant==='subnet'&&options.interactive)scene.setSubnet(Number(document.querySelector('#prefix')?.value||24));scenes.push(scene);return scene;}catch{el.innerHTML='<div class="no-webgl">แบบจำลอง 3 มิติใช้งานไม่ได้ในเบราว์เซอร์นี้<br>ยังอ่านบทเรียนและทดลองผ่านตัวควบคุมด้านล่างได้</div>';return null;}}).catch(()=>{if(el.isConnected)el.innerHTML='<div class="no-webgl">โหลดแบบจำลองไม่ได้ กรุณาตรวจการเชื่อมต่ออินเทอร์เน็ต<br>ยังทดลองและอ่านผลผ่านตัวควบคุมด้านล่างได้</div>';return null;});}
function destroyScenes(){disposed=!disposed;scenes.forEach(s=>s.dispose());scenes=[];}
function clearWorker(){worker?.terminate();worker=null;workerReady=false;clearTimeout(runTimer);clearTimeout(initTimer);}
function intro(title,desc,label='YOUR FIELD GUIDE'){return `<section class="intro"><div><p class="eyebrow">${label}</p><h1>${title}</h1><p>${desc}</p></div><span class="number">NETWORK → CODE → AI</span></section>`;}
function card(l){return `<a class="card ${progress[l.id]?'done':''}" href="#lesson/${l.id}"><div class="card-visual" data-scene="${l.visual}"><span class="label">${l.tag}</span><span class="lab-badge">${l.track==='network'?'3D INTERACTIVE':'LIVE PYTHON'}</span></div><div class="card-body"><h3>${l.title}</h3><p>${l.subtitle}</p><div class="card-meta"><span>${l.time} นาที · เริ่มต้น</span><span class="${progress[l.id]?'complete-badge':'go'}">${progress[l.id]?'✓ เรียนผ่านแล้ว':'เริ่มสำรวจ ↗'}</span></div></div></a>`;}
function renderExplore(){main.className='';currentLesson=null;const next=lessons.find(l=>!progress[l.id])||lessons[0];main.innerHTML=`${intro('<strong>ห้องทดลอง</strong>เทคโนโลยี','เริ่มจากเครือข่าย เขียนโค้ด แล้วสร้างเครื่องมือ AI')}<section class="hero"><div class="hero-copy"><p class="eyebrow">01 / EXPLORE THE CONNECTION</p><span class="chip">NETWORK FOUNDATIONS</span><h2>ทุกการเชื่อมต่อ<br>มีเรื่องราว<em>ระหว่างทาง</em></h2><p>หมุนดูอุปกรณ์ ส่ง Packet และค้นพบว่าข้อมูล<br>จากเครื่องของเราไปถึง Server ได้อย่างไร</p><a class="button" href="#lesson/${next.id}">${countDone()?'เรียนต่อจากครั้งก่อน':'เริ่มสำรวจเครือข่าย'}</a></div><div class="hero-stage" id="hero-scene"></div><div class="hero-tags"><span>CLIENT</span><span>— SWITCH —</span><span>ROUTER — SERVER</span></div></section><div class="filterbar" role="group" aria-label="กรองบทเรียน"><button class="filter active" data-filter="all">ทั้งหมด <span>12</span></button><button class="filter" data-filter="network">Network</button><button class="filter" data-filter="python">Python</button><button class="filter" data-filter="completed">เรียนผ่านแล้ว</button><label class="search"><input id="search" type="search" placeholder="ค้นหาบทเรียน…" aria-label="ค้นหาบทเรียน"></label></div><div id="catalog"></div><section class="future" aria-label="เส้นทางต่อยอด"><a class="future-item" href="#path"><strong>Python for Data</strong><span>อ่าน Log · CSV · API / ระยะถัดไป</span></a><a class="future-item" href="#path"><strong>JavaScript</strong><span>จาก Python สู่หน้าเว็บ / ระยะถัดไป</span></a><a class="future-item" href="#path"><strong>TypeScript + Node.js</strong><span>ข้อมูลที่ชัดเจน · บริการ API / ระยะถัดไป</span></a><a class="future-item" href="#path"><strong>Artificial Intelligence</strong><span>ค้นคู่มือ · สรุป Incident / ระยะถัดไป</span></a></section>`;addScene(document.querySelector('#hero-scene'),{hero:true});let filter='all';function draw(){const query=document.querySelector('#search').value.trim().toLowerCase();const visible=lessons.filter(l=>(filter==='all'||l.track===filter||(filter==='completed'&&progress[l.id]))&&`${l.title} ${l.subtitle} ${l.tag}`.toLowerCase().includes(query));const catalog=document.querySelector('#catalog');const catalogScenes=scenes.splice(1);catalogScenes.forEach(s=>s.dispose());catalog.innerHTML=['network','python'].map(track=>{const list=visible.filter(l=>l.track===track);if(!list.length)return '';return `<section><div class="section-heading"><span class="section-index">${track==='network'?'01':'02'}</span><h2>${track==='network'?'เข้าใจเครือข่าย':'เริ่มเขียนโปรแกรม'}</h2><span class="en">${track==='network'?'NETWORK':'PYTHON'}</span><span class="desc">${track==='network'?'มองเห็นการเชื่อมต่อ ก่อนเขียนโค้ด':'เปลี่ยนข้อมูลอุปกรณ์ ให้เป็นเครื่องมือช่วยงาน'}</span></div><div class="cards">${list.map(card).join('')}</div></section>`;}).join('')||'<div class="empty">ยังไม่มีบทเรียนที่ตรงกับตัวกรองนี้ ลองเปลี่ยนคำค้นหาหรือเลือกทั้งหมด</div>';catalog.querySelectorAll('[data-scene]').forEach(el=>addScene(el,{variant:el.dataset.scene}));}draw();document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));draw();}));document.querySelector('#search').addEventListener('input',draw);}
function renderPath(){main.className='';main.innerHTML=`${intro('เส้นทางของคุณ','เริ่มจากสิ่งที่มองเห็น แล้วค่อย ๆ สร้างสิ่งที่ใช้งานได้','THE LEARNING PATH')}<div class="path-grid"><div>${phases.map(([name,desc,key],i)=>{const list=lessons.filter(l=>l.track===key);return `<article class="path-item"><span class="path-number">0${i+1}</span><div><h2>${name}</h2><p>${desc}</p>${list.length?`<div class="path-lessons">${list.map(l=>`<a href="#lesson/${l.id}">${progress[l.id]?'✓ ':''}${l.title}</a>`).join('')}</div>`:'<span class="notice">อยู่ในแผนระยะถัดไป · ยังไม่มีบทเรียนให้ทดลอง</span>'}</div></article>`;}).join('')}</div><aside class="side-note"><p class="eyebrow">ONE CONNECTED JOURNEY</p><h2>เรื่องเดิม<br>มุมมองที่ลึกขึ้น</h2><p>Network ทำให้เข้าใจอุปกรณ์ Python ช่วยจัดการข้อมูล JavaScript และ Node.js เปิดข้อมูลให้คนอื่นใช้ แล้ว AI ช่วยค้นหาและสรุปจากหลักฐาน</p><p>เริ่มจากบทแรก หรือเปิดบทที่ต้องการทบทวนได้ทันที แต่ละบทมีคำใบ้และตัวอย่าง</p><a class="button" href="#lesson/packet">เริ่มบทแรก</a></aside></div>`;}
function renderProgress(){main.className='';const done=countDone();const minutes=lessons.filter(l=>progress[l.id]).reduce((n,l)=>n+l.time,0);main.innerHTML=`${intro('เห็นทุกก้าวที่เดินมา','ความคืบหน้านี้เก็บอยู่ในเบราว์เซอร์และเครื่องที่คุณกำลังใช้งาน','YOUR PROGRESS')}<div class="stat-grid"><div class="stat"><strong>${done}<small style="font-size:18px"> / 12</small></strong><span>บทเรียนที่ทำภารกิจผ่าน</span></div><div class="stat"><strong>${Math.round(done/12*100)}%</strong><span>เส้นทางพื้นฐานที่เรียนผ่าน</span></div><div class="stat"><strong>${minutes}</strong><span>นาทีตามเวลาประมาณของบทที่ผ่าน</span></div></div><div class="progress-list">${lessons.map(l=>`<a class="progress-row" href="#lesson/${l.id}"><span>${l.title}</span><span class="${progress[l.id]?'complete-badge':'notice'}">${progress[l.id]?'✓ ผ่านภารกิจแล้ว':'เริ่มเรียน ↗'}</span></a>`).join('')}</div><p class="notice">${storageAvailable?'ความคืบหน้าจะยังอยู่เมื่อกลับมาเปิดหน้าเดิม การล้างข้อมูลเบราว์เซอร์จะลบความคืบหน้านี้':'เบราว์เซอร์นี้ไม่อนุญาตให้บันทึกข้อมูล ความคืบหน้าจะอยู่เฉพาะระหว่างเปิดหน้านี้'}</p>`;}
function deviceTable(){return `<table class="device-table"><thead><tr><th>Device</th><th>IP address</th><th>Status</th><th>Alarm</th></tr></thead><tbody>${devices.map(d=>`<tr><td>${d.name}</td><td>${d.ip}</td><td><span class="status ${d.status}">${d.status}</span></td><td>${d.alarms}</td></tr>`).join('')}</tbody></table>`;}
function renderProject(){main.className='';main.innerHTML=`${intro('โปรเจกต์ที่เติบโตไปกับคุณ','อุปกรณ์ชุดเดิม ข้อมูลชุดเดิม เพิ่มความสามารถทีละขั้น','BUILD AS YOU LEARN')}<section class="project-banner"><div><p class="eyebrow">YOUR FIRST OPERATIONS TOOL</p><h2>Telecom Operations Lab</h2><p>จากการเข้าใจเครือข่าย สู่เครื่องมือสรุปอุปกรณ์ที่มีปัญหา ใช้สถานการณ์จำลองชุดเดียวกับทุกบทเรียน</p><a class="button" href="#lesson/offline">สร้างรายงานแรกด้วย Python</a></div><div class="project-stage"><p class="eyebrow">EXPECTED REPORT</p><code>OFFLINE DEVICES</code><code>AP-02 · 192.168.10.20 · 3 alarms</code><code>SW-03 · 192.168.10.3 · 2 alarms</code><code>────────────────────────</code><code>TOTAL ALARMS: 5</code></div></section>${deviceTable()}<section class="project-stages"><article><p class="eyebrow">01 / AVAILABLE NOW</p><h3>เข้าใจและคัดกรอง</h3><p>ตรวจเส้นทางเชื่อมต่อ แล้วใช้ Python เลือกอุปกรณ์ Offline และนับ Alarm</p><a class="button light small" href="#lesson/offline">เปิดห้องทดลอง</a></article><article><p class="eyebrow">02 / NEXT CHAPTER</p><h3>สร้างหน้าจอและ API</h3><p>ต่อยอดด้วย JavaScript, TypeScript และ Node.js เพื่อแสดงสถานะและบันทึก Incident</p><span class="notice">อยู่ในแผนระยะถัดไป</span></article><article><p class="eyebrow">03 / NEXT CHAPTER</p><h3>ค้นคู่มือด้วย AI</h3><p>ใช้ Python เตรียมข้อมูลให้ AI ช่วยค้นคู่มือและร่างสรุปจากหลักฐาน พร้อมตรวจคุณภาพคำตอบ</p><span class="notice">อยู่ในแผนระยะถัดไป</span></article></section>`;}
function lessonPanel(l){return `<aside class="lesson-panel"><p class="eyebrow">${l.tag}</p><h2>${l.title}</h2><span class="notice">${l.time} นาที · สำหรับผู้เริ่มต้น</span><div class="scenario">${l.scenario}</div><p>${l.explain}</p><ol class="steps">${l.steps.map(s=>`<li>${s}</li>`).join('')}</ol><p><strong>เชื่อมกับงาน</strong><br>${l.work}</p><button class="button light small open-terms">เปิดศัพท์ที่เกี่ยวข้อง</button><p class="sources">อ่านเพิ่มเติม: <a href="${l.source}" target="_blank" rel="noopener noreferrer">เอกสารอ้างอิง ↗</a></p></aside>`;}
function networkControls(l){if(l.id==='gateway')return '<label>Default gateway<select id="gateway"><option value="192.168.10.254">192.168.10.254 (ค่าเริ่มต้น)</option><option value="192.168.10.1">192.168.10.1</option><option value="10.0.0.10">10.0.0.10</option></select></label>';if(l.id==='dns')return '<label>ชื่อที่ต้องการค้นหา<select id="hostname"><option value="ops.example.test">ops.example.test</option><option value="missing.example.test">missing.example.test</option></select></label>';if(l.id==='protocols')return '<label>Protocol<select id="protocol"><option>TCP</option><option>UDP</option></select></label><label>Port<select id="port"><option value="443">443 · HTTPS</option><option value="5000">5000 · Telemetry</option></select></label>';if(l.id==='subnet')return '<label>Prefix ของ subnet<select id="prefix"><option value="24">/24</option><option value="25">/25</option><option value="26">/26</option></select></label>';return '<label>ปลายทาง<select id="destination"><option value="server">Server · 10.0.0.10</option><option value="local">SW-01 · 192.168.10.2</option></select></label>';}
function renderLesson(id){const l=lessons.find(l=>l.id===id);if(!l){main.className='';main.innerHTML=`${intro('ไม่พบบทเรียนนี้','เลือกบทเรียนจากคลังเพื่อเริ่มทดลอง')}<a class="button" href="#explore">กลับไปสำรวจบทเรียน</a>`;return;}currentLesson=l;main.className='lab-page';const idx=lessons.indexOf(l);main.innerHTML=`<div class="lab-head"><a class="back" href="#explore">‹ คลังบทเรียน</a><h1>${l.title}</h1><span class="lesson-tag">${String(idx+1).padStart(2,'0')} / 12 · ${l.tag}</span></div><div class="lab-layout">${lessonPanel(l)}<section class="workarea">${l.track==='network'?`<div class="network-view" id="network-scene"><div class="scene-note">LIVE NETWORK MODEL · ${l.id==='subnet'?'192.168.10.0/24':'CLIENT 192.168.10.25/24'}</div><div class="scene-legend"><span>ลากเพื่อหมุน · เลื่อนเพื่อซูม</span><span><b>●</b> Packet · แบบจำลองเพื่อการเรียนรู้</span></div></div><div class="control-panel"><div class="controls">${networkControls(l)}<button class="button" id="send-packet">${l.id==='subnet'?'ดูช่วง IP':l.id==='dns'?'ค้นชื่อและเชื่อมต่อ':'ส่ง Packet'}</button><button class="button light" id="reset-view">รีเซ็ตมุมมอง</button></div><div class="trace" id="trace" role="status" aria-live="polite">${l.id==='gateway'?'Gateway ที่ตั้งไว้ยังไม่ตรงกับ Router ลองส่ง Packet เพื่อตรวจปัญหา':l.id==='subnet'?'เลือก prefix แล้วดูการแบ่งช่วง IP':'เลือกค่าที่ต้องการ แล้วเริ่มทดลองส่งข้อมูล'}</div></div><div class="question-box"><p class="eyebrow">YOUR MISSION</p><h3>${l.question}</h3><div class="choices">${l.choices.map((s,i)=>`<button class="choice" data-answer="${i}">${s}</button>`).join('')}</div><button class="hint" id="hint">ขอคำใบ้</button><div class="feedback" id="feedback" aria-live="polite">${progress[l.id]?'✓ คุณเคยผ่านภารกิจนี้แล้ว ทดลองทบทวนได้อีกครั้ง':''}</div></div>`:`<div class="editor-wrap"><div class="editor-bar"><span>${l.id}.py</span><span>PYTHON · IN YOUR BROWSER</span></div><label for="code" class="skip">โค้ด Python ที่แก้ไขได้</label><textarea class="editor" id="code" spellcheck="false" aria-label="โค้ด Python ที่แก้ไขได้">${escapeHTML(drafts[l.id]||l.starter)}</textarea><div class="editor-actions"><button class="button small" id="run-code" disabled>กำลังเตรียม Python…</button><button class="button light small" id="reset-code">เริ่มโค้ดใหม่</button><span id="python-status" aria-live="polite">โหลดครั้งแรกอาจใช้เวลาสักครู่</span></div><pre class="output" id="output" role="log" aria-live="polite">ผลลัพธ์จะปรากฏที่นี่</pre></div><div class="question-box"><p class="eyebrow">YOUR MISSION</p><h3>แก้โค้ดให้ได้ผลลัพธ์นี้</h3><pre class="output" style="border-radius:7px">${escapeHTML(l.expected)}</pre><button class="hint" id="hint">ขอคำใบ้</button><button class="hint" id="solution" style="margin-left:20px">ดูตัวอย่างเฉลย</button><div class="feedback" id="feedback" aria-live="polite">${progress[l.id]?'✓ คุณเคยผ่านภารกิจนี้แล้ว ทดลองทบทวนได้อีกครั้ง':''}</div></div>${l.id==='offline'?deviceTable():''}`}<div class="lesson-links">${idx>0?`<a href="#lesson/${lessons[idx-1].id}">‹ บทก่อนหน้า</a>`:''}${idx<lessons.length-1?`<a style="margin-left:auto" href="#lesson/${lessons[idx+1].id}">บทถัดไป ›</a>`:'<a href="#project">ดูโปรเจกต์สะสม ›</a>'}</div></section></div>`;document.querySelector('.open-terms').addEventListener('click',openGlossary);document.querySelector('#hint').addEventListener('click',()=>{const fb=document.querySelector('#feedback');fb.className='feedback';fb.textContent=l.hint;});if(l.track==='network')initNetwork(l);else initPython(l);}
function initNetwork(l){const scenePromise=addScene(document.querySelector('#network-scene'),{variant:l.id==='subnet'?'subnet':'network',interactive:true});let experimented=false;let success=false;const trace=document.querySelector('#trace');document.querySelector('#reset-view').addEventListener('click',async()=>{(await scenePromise)?.reset();});document.querySelector('#send-packet').addEventListener('click',async()=>{const button=document.querySelector('#send-packet');button.disabled=true;trace.classList.remove('error');trace.textContent='กำลังทดลอง…';const scene=await scenePromise;if(currentLesson!==l)return;let hops=3;let ok=true;let lines=[];if(l.id==='gateway'){const gateway=document.querySelector('#gateway').value;ok=gateway==='192.168.10.1';hops=ok?3:1;lines=ok?['✓ Client → Switch → Gateway 192.168.10.1 → Server 10.0.0.10','เชื่อมต่อสำเร็จ: ตั้งค่า Default gateway ตรงกับ Router แล้ว']:['✕ Client → Switch → หยุดก่อนถึง Gateway',`ไม่มี Router ที่ใช้ ${gateway} บน LAN นี้ ข้อมูลจึงออกไปยัง Server ไม่ได้ ลองเปลี่ยนเป็น 192.168.10.1`];}else if(l.id==='dns'){const host=document.querySelector('#hostname').value;ok=host==='ops.example.test';hops=ok?3:0;lines=ok?['✓ DNS: ops.example.test → 10.0.0.10','✓ เชื่อมต่อ TCP/443 แล้วได้รับ HTTP 200 จากบริการจำลอง']:['✕ DNS: NXDOMAIN — ไม่มีชื่อ missing.example.test ใน DNS จำลอง','ยังไม่ได้เริ่มเชื่อมต่อ HTTP ลองเลือกชื่อ ops.example.test'];}else if(l.id==='protocols'){const protocol=document.querySelector('#protocol').value;const port=document.querySelector('#port').value;ok=(protocol==='TCP'&&port==='443')||(protocol==='UDP'&&port==='5000');lines=ok?[`✓ ส่งถึง Server ด้วย ${protocol}/${port}`,protocol==='TCP'?'บริการ HTTPS จำลองตอบกลับ การส่งจริงแบบ TCP มีกลไกจัดลำดับและส่งซ้ำ':'บริการ Telemetry จำลองได้รับ datagram ครั้งนี้ UDP เองไม่รับประกันการส่งถึงทุกครั้ง']:[`✕ ไม่มีบริการจำลองที่ ${protocol}/${port}`,'เลือก TCP/443 สำหรับ HTTPS หรือ UDP/5000 สำหรับ Telemetry การถึง IP ไม่ได้แปลว่าบริการที่เลือกเปิดอยู่'];}else if(l.id==='subnet'){const prefix=Number(document.querySelector('#prefix').value);const size=2**(32-prefix);const count=256/size;lines=[`/${prefix}: ${count} subnet · ${size} ที่อยู่ต่อ subnet · ${size-2} host ใช้งานต่อ subnet (LAN IPv4 ทั่วไป)`,...Array.from({length:count},(_,i)=>`192.168.10.${i*size}/${prefix} → host .${i*size+1} ถึง .${(i+1)*size-2} · broadcast .${(i+1)*size-1}`)];ok=true;hops=0;}else{const local=document.querySelector('#destination').value==='local';hops=local?1:3;lines=local?['✓ Client 192.168.10.25 → Switch → SW-01 192.168.10.2','อยู่ใน 192.168.10.0/24 เหมือนกัน ข้อมูลไปถึงปลายทางบน LAN โดยไม่ต้องผ่าน Router']:['✓ Client → Switch → Router 192.168.10.1 → Server 10.0.0.10','ปลายทางอยู่คนละ subnet จึงส่งผ่าน Default gateway แบบจำลองนี้รวมขั้นตอนบางส่วนเพื่อให้เห็นภาพ'];}if(hops)await scene?.send(hops,!ok);if(currentLesson!==l)return;trace.innerHTML=lines.map(x=>`<div>${escapeHTML(x)}</div>`).join('');trace.classList.toggle('error',!ok);experimented=true;success=ok;button.disabled=false;});document.querySelectorAll('[data-answer]').forEach(button=>button.addEventListener('click',()=>{const fb=document.querySelector('#feedback');if(!experimented){fb.className='feedback bad';fb.textContent='ลองใช้ตัวควบคุมส่งข้อมูลหรือดูช่วง IP ก่อนตอบภารกิจ';return;}if(l.id==='gateway'&&!success){fb.className='feedback bad';fb.textContent='แก้ Gateway แล้วส่ง Packet ให้สำเร็จก่อน เพื่อยืนยันว่าคุณแก้สาเหตุได้';return;}const correct=Number(button.dataset.answer)===l.answer;fb.className=correct?'feedback':'feedback bad';fb.textContent=correct?`✓ ผ่านภารกิจแล้ว — ${l.reason}`:`ลองอีกครั้ง — ${l.reason}`;if(correct)complete(l.id);}));}
function initPython(l){const run=document.querySelector('#run-code');const output=document.querySelector('#output');const status=document.querySelector('#python-status');const code=document.querySelector('#code');code.addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const start=code.selectionStart,end=code.selectionEnd;code.setRangeText('    ',start,end,'end');code.dispatchEvent(new Event('input'));}});code.addEventListener('input',()=>{drafts[l.id]=code.value;try{localStorage.setItem('techatlas-drafts-v1',JSON.stringify(drafts));}catch{}});document.querySelector('#reset-code').addEventListener('click',()=>{code.value=l.starter;code.dispatchEvent(new Event('input'));output.textContent='รีเซ็ตโค้ดแล้ว กดรันเพื่อทดลองอีกครั้ง';});document.querySelector('#solution').addEventListener('click',()=>{document.querySelector('#feedback').textContent='ตัวอย่างเฉลยปรากฏด้านล่าง ลองพิมพ์และอธิบายแต่ละบรรทัดด้วยตัวเอง';let pre=document.querySelector('#solution-code');if(!pre){pre=document.createElement('pre');pre.id='solution-code';pre.className='output';pre.style.cssText='margin-top:15px;border-radius:7px;overflow:auto';document.querySelector('#feedback').after(pre);}pre.textContent=l.solution;});function boot(){clearWorker();worker=new Worker('assets/python-worker.js');worker.postMessage({type:'init'});run.disabled=true;run.textContent='กำลังเตรียม Python…';status.textContent='โหลด Python ครั้งแรก อาจใช้เวลา 10–40 วินาที';initTimer=setTimeout(()=>{clearWorker();run.disabled=false;run.textContent='ลองโหลด Python ใหม่';status.textContent='โหลดไม่สำเร็จ ตรวจอินเทอร์เน็ตแล้วลองใหม่';},60000);worker.onmessage=({data})=>{if(currentLesson!==l)return;if(data.type==='ready'){clearTimeout(initTimer);workerReady=true;run.disabled=false;run.textContent='▶ รันโค้ด';status.textContent='Python พร้อม · โค้ดรันในเครื่องนี้';return;}clearTimeout(runTimer);run.disabled=false;run.textContent='▶ รันโค้ด';if(data.type==='result'){output.textContent=data.output||'(โปรแกรมทำงานจบโดยไม่มีข้อความจาก print)';status.textContent='รันเสร็จแล้ว';const normalized=data.output.trim().replace(/\r\n/g,'\n');const correct=normalized===l.expected.trim();const fb=document.querySelector('#feedback');fb.className=correct?'feedback':'feedback bad';fb.textContent=correct?'✓ ผ่านภารกิจแล้ว ผลลัพธ์ตรงกับโจทย์ ลองอธิบายว่าแต่ละบรรทัดทำอะไร':'โปรแกรมทำงานแล้ว แต่ผลลัพธ์ยังไม่ตรงโจทย์ ลองเทียบทีละบรรทัด หรือเปิดคำใบ้';if(correct)complete(l.id);}else{output.textContent=data.message;status.textContent='พบข้อผิดพลาด';const fb=document.querySelector('#feedback');fb.className='feedback bad';fb.textContent=data.message.includes('SyntaxError')?'รูปแบบโค้ดยังไม่ถูกต้อง ตรวจเครื่องหมาย : วงเล็บ และเครื่องหมายคำพูด':data.message.includes('IndentationError')?'ตรวจการเยื้องบรรทัดภายใน if / for / def ให้ตรงกัน':data.message.includes('KeyError')?'ไม่พบ key ในข้อมูล ตรวจชื่อช่องหรือใช้ get() พร้อมค่าเริ่มต้น':'อ่านบรรทัดท้ายของข้อผิดพลาด แล้วตรวจตัวแปรและคำสั่งในบรรทัดที่ระบุ';if(!workerReady){clearWorker();run.textContent='ลองโหลด Python ใหม่';status.textContent='โหลด Python ไม่สำเร็จ ตรวจอินเทอร์เน็ตแล้วลองอีกครั้ง';}}};worker.onerror=()=>{clearWorker();run.disabled=false;run.textContent='ลองโหลด Python ใหม่';status.textContent='โหลด Python ไม่สำเร็จ';};}boot();run.addEventListener('click',()=>{if(!workerReady){boot();return;}if(code.value.length>20000){output.textContent='โค้ดยาวเกินขอบเขตห้องทดลองนี้ (20,000 ตัวอักษร)';return;}run.disabled=true;run.textContent='กำลังรัน…';status.textContent='กำลังประมวลผล';output.textContent='';worker.postMessage({type:'run',code:code.value,id:l.id});runTimer=setTimeout(()=>{clearWorker();output.textContent='หยุดโปรแกรมหลัง 8 วินาที: อาจมี Loop ที่ไม่จบ ลองตรวจเงื่อนไขแล้วโหลด Python ใหม่';run.disabled=false;run.textContent='ลองโหลด Python ใหม่';status.textContent='หยุดโปรแกรมแล้ว';},8000);});}
function openGlossary(){document.querySelector('#glossary').showModal();}
document.querySelector('#terms').innerHTML=terms.map(([term,desc])=>`<div class="term"><strong>${term}</strong><p>${desc}</p></div>`).join('');document.querySelector('#glossary-open').addEventListener('click',openGlossary);document.querySelector('#glossary .close').addEventListener('click',()=>document.querySelector('#glossary').close());document.querySelector('#glossary').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close();}});
function route(){destroyScenes();clearWorker();currentLesson=null;const hash=location.hash.slice(1)||'explore';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash===`#${hash}`||(hash.startsWith('lesson/')&&a.hash==='#explore')));if(hash.startsWith('lesson/'))renderLesson(hash.split('/')[1]);else if(hash==='path')renderPath();else if(hash==='project')renderProject();else if(hash==='progress')renderProgress();else renderExplore();document.title=currentLesson?`${currentLesson.title} · TechAtlas`:'TechAtlas · ห้องทดลองเทคโนโลยี';window.scrollTo(0,0);updateBadge();}
document.addEventListener('change',event=>{if(event.target.id==='prefix'){scenes.find(s=>s.container.id==='network-scene')?.setSubnet(Number(event.target.value));document.querySelector('#trace').textContent='ภาพแสดงจำนวน subnet ตาม prefix ที่เลือก กดดูช่วง IP เพื่ออ่านรายละเอียด';}});
window.addEventListener('hashchange',route);route();
if(document.modelContext?.registerTool){const tools=[{name:'read_learning_progress',description:'Read completed lessons and the available curriculum.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({completed:lessons.filter(l=>progress[l.id]).map(l=>l.id),available:lessons.map(l=>({id:l.id,title:l.title}))})},{name:'open_lesson',description:'Navigate to an available lesson. Does not complete the lesson.',inputSchema:{type:'object',properties:{lessonId:{type:'string',enum:lessons.map(l=>l.id)}},required:['lessonId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||!lessons.some(l=>l.id===input.lessonId))throw new Error('Unknown lesson');location.hash=`lesson/${input.lessonId}`;await new Promise(r=>setTimeout(r,50));return {opened:input.lessonId,title:lessons.find(l=>l.id===input.lessonId).title};}}];for(const tool of tools)try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}
